<?php

/* @autogenerated */
declare(strict_types=1);

use PHPUnit\Framework\TestCase;
use Civi\Lughauth\Shared\Exception\ConstraintException;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use Civi\Lughauth\Features\Access\TrustedClient\Domain\ValueObject\TrustedClientIdTokenSignedResponseAlgVO;
use Civi\Lughauth\Features\Access\TrustedClient\Domain\TrustedClientIdTokenSignedResponseAlgOptions;

final class TrustedClientIdTokenSignedResponseAlgVOUnitTest extends TestCase
{
    public function test_asignation_keep_value(): void
    {
        $value = TrustedClientIdTokenSignedResponseAlgOptions::RS256;
        $ref = TrustedClientIdTokenSignedResponseAlgVO::from($value);
        $this->assertEquals(TrustedClientIdTokenSignedResponseAlgOptions::RS256, $ref->value());
        $other = TrustedClientIdTokenSignedResponseAlgVO::tryFrom($ref, new ConstraintFailList());
        $this->assertSame($other, $ref);
        $more = TrustedClientIdTokenSignedResponseAlgVO::from($ref);
        $this->assertSame($more, $ref);
    }
    public function test_asignation_invalid_type(): void
    {
        $errors = new ConstraintFailList();
        $other = TrustedClientIdTokenSignedResponseAlgVO::tryFrom('1', $errors);
        $this->assertNull($other);
        $this->assertTrue($errors->hasErrors());
    }
    public function test_optimist_asignation_invalid_type(): void
    {
        $this->expectException(ConstraintException::class);
        $method = new ReflectionMethod(TrustedClientIdTokenSignedResponseAlgVO::class, 'fromUnsafe');
        $method->invoke(null, [11, "bad"]);
    }
    public function test_equals(): void
    {
        $one = TrustedClientIdTokenSignedResponseAlgVO::from(TrustedClientIdTokenSignedResponseAlgOptions::RS256);
        $same = TrustedClientIdTokenSignedResponseAlgVO::from(TrustedClientIdTokenSignedResponseAlgOptions::RS256);
        $other = TrustedClientIdTokenSignedResponseAlgVO::from(TrustedClientIdTokenSignedResponseAlgOptions::ES256);
        $withEmpty = $one->equals(null);
        $withSame = $one->equals($same);
        $withOther = $one->equals($other);

        $this->assertFalse($withEmpty);
        $this->assertTrue($withSame);
        $this->assertFalse($withOther);
    }
    public function test_empty(): void
    {
        $ref = TrustedClientIdTokenSignedResponseAlgVO::empty();
        $this->assertNull($ref->value());
    }
    public function test_try_from_empty(): void
    {
        $ref = TrustedClientIdTokenSignedResponseAlgVO::tryFrom(null, new ConstraintFailList());
        $this->assertNull($ref->value());
    }
}
